32	/**
33	 * Runs the full analysis pipeline from configuration to project model.
34	 */
35	final class ProjectAnalyzer
36	{
37	    /** @readonly */
38	    private PackageDiscovery $discovery;
39	
40	    /** @readonly */
41	    private PackageGraphBuilder $graphBuilder;
42	
43	    /** @readonly */
44	    private DocGenPathResolver $pathResolver;
45	
46	    /** @readonly */
47	    private ProjectSymbolCollector $symbolCollector;
48	
49	    /** @readonly */
50	    private DeptracConfigReader $deptracReader;
51	
52	    /** @readonly */
53	    private LayerAssigner $layerAssigner;
54	
55	    /** @readonly */
56	    private CoverageReader $coverageReader;
57	
58	    /** @readonly */
59	    private DocumentCollector $documentCollector;
60	
61	    /**
62	     * Creates a project analyzer from pipeline collaborators.
63	     */
64	    public function __construct(
65	        ?PackageDiscovery $discovery = null,
66	        ?PackageGraphBuilder $graphBuilder = null,
67	        ?DocGenPathResolver $pathResolver = null,
68	        ?ProjectSymbolCollector $symbolCollector = null,
69	        ?DeptracConfigReader $deptracReader = null,
70	        ?LayerAssigner $layerAssigner = null,
71	        ?CoverageReader $coverageReader = null,
72	        ?DocumentCollector $documentCollector = null,
73	    ) {
74	        $this->discovery = $discovery ?? new PackageDiscovery();
75	        $this->graphBuilder = $graphBuilder ?? new PackageGraphBuilder();
76	        $this->pathResolver = $pathResolver ?? new DocGenPathResolver();
77	        $this->symbolCollector = $symbolCollector ?? new ProjectSymbolCollector();
78	        $this->deptracReader = $deptracReader ?? new DeptracConfigReader();
79	        $this->layerAssigner = $layerAssigner ?? new LayerAssigner();
80	        $this->coverageReader = $coverageReader ?? new CoverageReader();
81	        $this->documentCollector = $documentCollector ?? new DocumentCollector();
82	    }
83	
84	    /**
85	     * Analyzes one configured project into its documentation model.
86	     *
87	     * @throws DocGenException when no package or source can be analyzed
88	     */
89	    public function analyze(DocGenConfig $config, ?int $workers = null): ProjectModel
90	    {
91	        $packages = $this->discovery->discover($config);
92	        $collected = $this->symbolCollector->collect($config, $packages, $workers);
93	
94	        $symbolTable = new SymbolTable();
95	        foreach ($collected['classLikes'] as $classLike) {
96	            $symbolTable->registerClassLike($classLike);
97	        }
98	
99	        foreach ($collected['functions'] as $function) {
100	            $symbolTable->registerFunction($function);
101	        }
102	
103	        $hierarchy = new HierarchyIndex();
104	        $hierarchy->build($collected['classLikes']);
105	        $usages = new UsageIndex();
106	        $usages->build($collected['usages']);
107	        $coverage = $this->coverageIndex($config);
108	        $testCases = new TestCaseIndex();
109	        $testCases->build($collected['usages'], $collected['classLikes'], $coverage);
110	        $layers = $this->layerModel($config);
111	
112	        return new ProjectModel(
113	            $this->titleFor($config, $packages),
114	            $config->root,
115	            $packages,
116	            $this->graphBuilder->build($packages),
117	            $collected['classLikes'],
118	            $collected['functions'],
119	            $symbolTable,
120	            $hierarchy,
121	            $usages,
122	            $testCases,
123	            $layers,
124	            $this->layerAssignments($layers, $collected['classLikes']),
125	            $coverage,
126	            array_merge($this->vendorWarnings($config, $packages), $collected['warnings']),
127	            $this->documentCollector->collect($config, $packages),
128	        );
129	    }
130	
131	    /**
132	     * Warns about unusable vendor selections.
133	     *
134	     * Both the runtime globs of "vendor" and the dev globs of "vendor_dev" are
135	     * checked, and every selected package that ships no documentable source is
136	     * reported as well.
137	     *
138	     * @param list<DiscoveredPackage> $packages
139	     *
140	     * @return list<string>
141	     */
142	    public function vendorWarnings(DocGenConfig $config, array $packages): array
143	    {
144	        return array_merge(
145	            $this->vendorGlobWarnings($config->vendor, $packages, false),
146	            $this->vendorGlobWarnings($config->vendorDev, $packages, true),
147	            $this->vendorSourceWarnings($packages),
148	        );
149	    }
150	
151	    /**
152	     * Warns about vendor globs that selected no package of one kind.
153	     *
154	     * Vendor globs match composer package names, so a directory name such
155	     * as "vendor" silently selects nothing without this warning. A glob also
156	     * selects nothing when it names a dev dependency while the runtime globs
157	     * are checked, or the other way round.
158	     *
159	     * @param list<string> $globs
160	     * @param list<DiscoveredPackage> $packages
161	     * @param bool $dev true when the dev globs are checked, false for runtime globs
162	     *
163	     * @return list<string>
164	     */
165	    public function vendorGlobWarnings(array $globs, array $packages, bool $dev): array
166	    {
167	        $warnings = [];
168	        foreach ($globs as $glob) {
169	            $matched = false;
170	            foreach ($packages as $package) {
171	                if ($package->isVendor && $package->isDevDependency === $dev && fnmatch($glob, $package->manifest->name)) {
172	                    $matched = true;
173	                    break;
174	                }
175	            }
176	
177	            if (!$matched) {
178	                $warnings[] = sprintf(
179	                    'Vendor glob "%s" documented no installed %s vendor package. Vendor globs match composer package names such as "acme/lib" or "acme/*", not directory names.',
180	                    $glob,
181	                    $dev ? 'dev' : 'runtime',
182	                );
183	            }
184	        }
185	
186	        return $warnings;
187	    }
188	
189	    /**
190	     * Warns about selected vendor packages without documentable sources.
191	     *
192	     * A package that autoloads only "files" entries, such as a phar bootstrap,
193	     * exposes no source directory to parse, so none of its classes can appear
194	     * in the site or be used as a link target.
195	     *
196	     * @param list<DiscoveredPackage> $packages
197	     *
198	     * @return list<string>
199	     */
200	    public function vendorSourceWarnings(array $packages): array
201	    {
202	        $warnings = [];
203	        foreach ($packages as $package) {
204	            if ($package->isVendor && $this->symbolCollector->sourceDirectories($package) === []) {
205	                $warnings[] = sprintf(
206	                    'Vendor package "%s" declares no PSR-4 or classmap autoload source, so its classes cannot be documented or linked. Packages that autoload only "files" entries, such as a phar bootstrap, cannot be documented: drop "%s" from the vendor globs.',
207	                    $package->manifest->name,
208	                    $package->manifest->name,
209	                );
210	            }
211	        }
212	
213	        return $warnings;
214	    }
215	
216	    /**
217	     * Assigns every class-like symbol to its deptrac layers.
218	     *
219	     * @param list<Model\ClassLikeDoc> $classLikes
220	     *
221	     * @return array<string, list<string>>
222	     */
223	    public function layerAssignments(?LayerModel $layers, array $classLikes): array
224	    {
225	        if ($layers === null) {
226	            return [];
227	        }
228	
229	        $assignments = [];
230	        foreach ($classLikes as $classLike) {
231	            $names = $this->layerAssigner->assign($layers, $classLike);
232	            if ($names !== []) {
233	                $assignments[strtolower($classLike->fqcn)] = $names;
234	            }
235	        }
236	
237	        return $assignments;
238	    }
239	
240	    /**
241	     * Loads the deptrac layer model when a configuration is available.
242	     *
243	     * @throws DocGenException when a configured deptrac file is missing
244	     */
245	    public function layerModel(DocGenConfig $config): ?LayerModel
246	    {
247	        if ($config->deptrac !== null) {
248	            return $this->deptracReader->read($this->pathResolver->resolve($config->root, $config->deptrac));
249	        }
250	
251	        $default = $config->root . '/deptrac.yaml';
252	        if (is_file($default)) {
253	            return $this->deptracReader->read($default);
254	        }
255	
256	        return null;
257	    }
258	
259	    /**
260	     * Loads the coverage index when a report directory is configured.
261	     *
262	     * @throws DocGenException when the configured report directory is missing
263	     */
264	    public function coverageIndex(DocGenConfig $config): ?CoverageIndex
265	    {
266	        if ($config->coverage === null) {
267	            return null;
268	        }
269	
270	        return $this->coverageReader->read($this->pathResolver->resolve($config->root, $config->coverage), $config->root);
271	    }
272	
273	    /**
274	     * Determines the site title from the configuration and packages.
275	     *
276	     * @param list<DiscoveredPackage> $packages
277	     */
278	    public function titleFor(DocGenConfig $config, array $packages): string
279	    {
280	        if ($config->title !== null) {
281	            return $config->title;
282	        }
283	
284	        foreach ($packages as $package) {
285	            if (!$package->isVendor && realpath($package->manifest->directory) === realpath($config->root)) {
286	                return $package->manifest->name;
287	            }
288	        }
289	
290	        return basename($config->root);
291	    }
292	}
