29	/**
30	 * Parses the sources of every documented package into symbol lists.
31	 *
32	 * The files are parsed by worker processes, but the result is the result a
33	 * single process would have produced: the work is cut into consecutive
34	 * jobs, and the jobs are merged back in job order, so the order symbols and
35	 * references reach the site in never depends on how the work was divided.
36	 */
37	final class ProjectSymbolCollector
38	{
39	    /** @readonly */
40	    private SourceFileFinder $fileFinder;
41	
42	    /** @readonly */
43	    private DocGenPathResolver $pathResolver;
44	
45	    /** @readonly */
46	    private AstParser $astParser;
47	
48	    /** @readonly */
49	    private FileSymbolCollector $symbolCollector;
50	
51	    /** @readonly */
52	    private WorkerPool $workers;
53	
54	    /** @readonly */
55	    private WorkScheduler $scheduler;
56	
57	    /**
58	     * Creates a project symbol collector from its parsing collaborators.
59	     */
60	    public function __construct(
61	        ?SourceFileFinder $fileFinder = null,
62	        ?DocGenPathResolver $pathResolver = null,
63	        ?AstParser $astParser = null,
64	        ?FileSymbolCollector $symbolCollector = null,
65	        ?WorkerPool $workers = null,
66	        ?WorkScheduler $scheduler = null,
67	    ) {
68	        $this->fileFinder = $fileFinder ?? new SourceFileFinder();
69	        $this->pathResolver = $pathResolver ?? new DocGenPathResolver();
70	        $this->astParser = $astParser ?? new AstParser();
71	        $this->symbolCollector = $symbolCollector ?? new FileSymbolCollector();
72	        $this->workers = $workers ?? new WorkerPool();
73	        $this->scheduler = $scheduler ?? new WorkScheduler();
74	    }
75	
76	    /**
77	     * Parses all package sources into deduplicated symbol lists.
78	     *
79	     * @param list<DiscoveredPackage> $packages
80	     * @param ?int $workers how many workers to use, or null for the default
81	     *
82	     * @return array{classLikes: list<ClassLikeDoc>, functions: list<FunctionDoc>, warnings: list<string>, usages: list<Usage>}
83	     *
84	     * @throws DocGenException when a worker cannot finish its files
85	     */
86	    public function collect(DocGenConfig $config, array $packages, ?int $workers = null): array
87	    {
88	        $files = $this->sourceFiles($config, $packages);
89	
90	        return $this->merged($this->workers->map(
91	            $this->scheduler->plan($files, static fn (array $file): int => (int) @filesize($file['file']), $workers),
92	            fn (array $job): array => $this->parseJob($config, $job),
93	        ));
94	    }
95	
96	    /**
97	     * Lists every source file to parse, in discovery order and once each.
98	     *
99	     * @param list<DiscoveredPackage> $packages
100	     *
101	     * @return list<array{package: DiscoveredPackage, source: array{directory: string, isDev: bool}, file: string}>
102	     */
103	    public function sourceFiles(DocGenConfig $config, array $packages): array
104	    {
105	        $found = [];
106	        $seenFiles = [];
107	        foreach ($packages as $package) {
108	            foreach ($this->sourceDirectories($package) as $source) {
109	                foreach ($this->fileFinder->find($source['directory'], $config->root, $config->exclude) as $file) {
110	                    if (isset($seenFiles[$file])) {
111	                        continue;
112	                    }
113	
114	                    $seenFiles[$file] = true;
115	                    $found[] = ['package' => $package, 'source' => $source, 'file' => $file];
116	                }
117	            }
118	        }
119	
120	        return $found;
121	    }
122	
123	    /**
124	     * Parses the consecutive files of one job.
125	     *
126	     * One collector serves the whole job, as one collector served the whole
127	     * project before there were jobs. The usages it gathers stay in file
128	     * order, and the jobs themselves are consecutive, so concatenating the
129	     * jobs restores the order a single process would have produced.
130	     *
131	     * @param list<array{package: DiscoveredPackage, source: array{directory: string, isDev: bool}, file: string}> $job
132	     *
133	     * @return array{symbols: list<FileSymbols|string>, usages: list<Usage>}
134	     */
135	    public function parseJob(DocGenConfig $config, array $job): array
136	    {
137	        $collector = new UsageCollector();
138	        $traverser = new NodeTraverser();
139	        $traverser->addVisitor($collector);
140	        $symbols = [];
141	        foreach ($job as $file) {
142	            $symbols[] = $this->collectFile($config, $file['package'], $file['source'], $file['file'], $collector, $traverser);
143	        }
144	
145	        return ['symbols' => $symbols, 'usages' => $collector->usages()];
146	    }
147	
148	    /**
149	     * Merges the job results into the deduplicated lists of the project.
150	     *
151	     * @param list<mixed> $results what every job reported, in job order
152	     *
153	     * @return array{classLikes: list<ClassLikeDoc>, functions: list<FunctionDoc>, warnings: list<string>, usages: list<Usage>}
154	     *
155	     * @throws DocGenException when a job reported something else
156	     */
157	    public function merged(array $results): array
158	    {
159	        $classLikes = [];
160	        $functions = [];
161	        $warnings = [];
162	        $usages = [];
163	        $seenSymbols = [];
164	        foreach ($results as $result) {
165	            $parsed = $this->parsed($result);
166	            foreach ($parsed['usages'] as $usage) {
167	                $usages[] = $usage;
168	            }
169	
170	            foreach ($parsed['symbols'] as $symbols) {
171	                if (is_string($symbols)) {
172	                    $warnings[] = $symbols;
173	                    continue;
174	                }
175	
176	                foreach ($symbols->classLikes as $classLike) {
177	                    if (!isset($seenSymbols[strtolower($classLike->fqcn)])) {
178	                        $seenSymbols[strtolower($classLike->fqcn)] = true;
179	                        $classLikes[] = $classLike;
180	                    }
181	                }
182	
183	                foreach ($symbols->functions as $function) {
184	                    if (!isset($seenSymbols[strtolower($function->fqn) . '()'])) {
185	                        $seenSymbols[strtolower($function->fqn) . '()'] = true;
186	                        $functions[] = $function;
187	                    }
188	                }
189	            }
190	        }
191	
192	        return ['classLikes' => $classLikes, 'functions' => $functions, 'warnings' => $warnings, 'usages' => $usages];
193	    }
194	
195	    /**
196	     * Reads what one job reported back as the parse result it must be.
197	     *
198	     * A job result comes from a worker process, so nothing about its shape
199	     * is guaranteed by the type system that produced it. Anything that is
200	     * not a parse result means the site would silently lose the files that
201	     * job held, which is worse than stopping.
202	     *
203	     * @param mixed $result
204	     *
205	     * @return array{symbols: list<FileSymbols|string>, usages: list<Usage>}
206	     *
207	     * @throws DocGenException when the job reported something else
208	     */
209	    public function parsed($result): array
210	    {
211	        $symbols = [];
212	        $usages = [];
213	        if (!is_array($result) || !isset($result['symbols'], $result['usages']) || !is_array($result['symbols']) || !is_array($result['usages'])) {
214	            throw new DocGenException('A documentation worker reported no parsed sources.');
215	        }
216	
217	        foreach ($result['symbols'] as $entry) {
218	            if (!is_string($entry) && !$entry instanceof FileSymbols) {
219	                throw new DocGenException('A documentation worker reported an unreadable source file.');
220	            }
221	
222	            $symbols[] = $entry;
223	        }
224	
225	        foreach ($result['usages'] as $usage) {
226	            if (!$usage instanceof Usage) {
227	                throw new DocGenException('A documentation worker reported an unreadable symbol reference.');
228	            }
229	
230	            $usages[] = $usage;
231	        }
232	
233	        return ['symbols' => $symbols, 'usages' => $usages];
234	    }
235	
236	    /**
237	     * Parses one source file and feeds it into the usage collector.
238	     *
239	     * @param array{directory: string, isDev: bool} $source
240	     *
241	     * @return FileSymbols|string the symbols, or a warning message
242	     */
243	    public function collectFile(DocGenConfig $config, DiscoveredPackage $package, array $source, string $file, UsageCollector $usageCollector, NodeTraverser $traverser)
244	    {
245	        $code = file_get_contents($file);
246	        if ($code === false) {
247	            return sprintf('Skipped unreadable file: %s', $file);
248	        }
249	
250	        $relative = $this->pathResolver->relative($config->root, $file);
251	        try {
252	            $statements = $this->astParser->parse($code, $relative);
253	        } catch (DocGenException $exception) {
254	            return $exception->getMessage();
255	        }
256	
257	        $symbols = $this->symbolCollector->collect($statements, $package->manifest->name, $relative, $source['isDev']);
258	        $usageCollector->beginFile($relative, $source['isDev']);
259	        $traverser->traverse($statements);
260	
261	        return $symbols;
262	    }
263	
264	    /**
265	     * Lists the autoload source directories of one package.
266	     *
267	     * PSR-4 prefixes always map to directories and are taken as declared; an
268	     * empty prefix path is the package root. Classmap entries may name a
269	     * directory or a single file, so only the entries that exist as a
270	     * directory are kept; single classmap files are not documented.
271	     *
272	     * @return list<array{directory: string, isDev: bool}>
273	     */
274	    public function sourceDirectories(DiscoveredPackage $package): array
275	    {
276	        $sources = [];
277	        foreach ([['map' => $package->manifest->autoload, 'isDev' => false], ['map' => $package->manifest->devAutoload, 'isDev' => true]] as $section) {
278	            foreach ($section['map'] as $directories) {
279	                foreach ($directories as $directory) {
280	                    $sources[] = [
281	                        'directory' => $directory === '' ? $package->manifest->directory : $this->pathResolver->resolve($package->manifest->directory, $directory),
282	                        'isDev' => $section['isDev'],
283	                    ];
284	                }
285	            }
286	        }
287	
288	        foreach ([['paths' => $package->manifest->classmap, 'isDev' => false], ['paths' => $package->manifest->devClassmap, 'isDev' => true]] as $section) {
289	            foreach ($section['paths'] as $path) {
290	                $directory = $this->pathResolver->resolve($package->manifest->directory, $path);
291	                if (is_dir($directory)) {
292	                    $sources[] = ['directory' => $directory, 'isDev' => $section['isDev']];
293	                }
294	            }
295	        }
296	
297	        return $sources;
298	    }
299	}
