41	/**
42	 * Runs the jobs of one generation phase in forked worker processes.
43	 *
44	 * Every job is forked once, works on its own share of the phase, and hands
45	 * its result back over a socket of its own. Results are returned in job
46	 * order rather than in the order the workers happened to finish, because
47	 * the site a run writes has to be the same site whatever the machine
48	 * scheduled first.
49	 *
50	 * A pool that cannot fork, or that has nothing worth splitting, runs the
51	 * jobs in this process instead. That is not a fallback for the sake of it:
52	 * it runs the same callable the workers run, so a sequential run and a
53	 * parallel run cannot drift apart.
54	 */
55	final class WorkerPool
56	{
57	    /** @readonly */
58	    private ForkSupport $fork;
59	
60	    /**
61	     * Creates a worker pool from its fork availability check.
62	     */
63	    public function __construct(?ForkSupport $fork = null)
64	    {
65	        $this->fork = $fork ?? new ForkSupport();
66	    }
67	
68	    /**
69	     * Runs every job and returns their results in job order.
70	     *
71	     * Results come back from another process, so they are returned as the
72	     * unvalidated values they are: what a phase expects of its own workers
73	     * is for that phase to state, not for the pool to assume.
74	     *
75	     * @template TJob
76	     *
77	     * @param list<TJob> $jobs
78	     * @param callable(TJob): mixed $work
79	     *
80	     * @return list<mixed>
81	     *
82	     * @throws DocGenException when a worker dies without a usable result
83	     */
84	    public function map(array $jobs, callable $work): array
85	    {
86	        if (count($jobs) < 2 || !$this->fork->isAvailable()) {
87	            return array_map($work, $jobs);
88	        }
89	
90	        $workers = [];
91	        foreach ($jobs as $index => $job) {
92	            $sockets = [];
93	            foreach ($workers as $started) {
94	                $sockets[] = $started['socket'];
95	            }
96	
97	            $worker = $this->start($job, $work, $sockets);
98	            if ($worker === null) {
99	                return $this->finish($workers, array_map($work, $this->remaining($jobs, $index)));
100	            }
101	
102	            $workers[] = $worker;
103	        }
104	
105	        return $this->finish($workers, []);
106	    }
107	
108	    /**
109	     * Forks one worker, or returns null when it could not be forked.
110	     *
111	     * The child closes the sockets of the workers forked before it, because
112	     * a socket left open in any process keeps the parent waiting for an end
113	     * of file that never comes. It drops the output buffers it inherited
114	     * for the same reason: a worker must not emit what the process that
115	     * forked it had buffered.
116	     *
117	     * @template TJob
118	     *
119	     * @param TJob $job
120	     * @param callable(TJob): mixed $work
121	     * @param list<resource> $openSockets the parent ends already handed out
122	     *
123	     * @return ?array{pid: int, socket: resource}
124	     */
125	    public function start($job, callable $work, array $openSockets): ?array
126	    {
127	        $pair = @stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);
128	        if (!is_array($pair)) {
129	            return null;
130	        }
131	
132	        $pid = pcntl_fork();
133	        if ($pid === -1) {
134	            fclose($pair[0]);
135	            fclose($pair[1]);
136	
137	            return null;
138	        }
139	
140	        if ($pid === 0) {
141	            fclose($pair[0]);
142	            foreach ($openSockets as $socket) {
143	                fclose($socket);
144	            }
145	
146	            while (ob_get_level() > 0) {
147	                ob_end_clean();
148	            }
149	
150	            @fwrite($pair[1], $this->payload($job, $work));
151	            fclose($pair[1]);
152	
153	            exit(0);
154	        }
155	
156	        fclose($pair[1]);
157	
158	        return ['pid' => $pid, 'socket' => $pair[0]];
159	    }
160	
161	    /**
162	     * Works one job and returns what its worker sends back.
163	     *
164	     * A job that throws reports the failure to the parent instead of
165	     * writing it to a terminal nobody is reading, so the run stops with the
166	     * message rather than with a site missing whatever that worker held.
167	     *
168	     * @template TJob
169	     *
170	     * @param TJob $job
171	     * @param callable(TJob): mixed $work
172	     */
173	    public function payload($job, callable $work): string
174	    {
175	        try {
176	            return $this->framed(serialize(['ok' => true, 'result' => $work($job)]));
177	        } catch (Throwable $exception) {
178	            return $this->framed(serialize(['ok' => false, 'result' => $exception->getMessage()]));
179	        }
180	    }
181	
182	    /**
183	     * Puts the byte count of a result in front of it.
184	     *
185	     * A worker that dies while writing leaves the parent with the first
186	     * part of a result and no way to tell that from a whole one. The count
187	     * makes a short result recognisable before anything tries to read it
188	     * as one, which is what keeps a half-finished run from being reported
189	     * as a finished one.
190	     */
191	    public function framed(string $body): string
192	    {
193	        return strlen($body) . "\n" . $body;
194	    }
195	
196	    /**
197	     * Reads the result out of a framed payload, or returns null.
198	     *
199	     * @param string|false $payload what the worker wrote to its socket
200	     *
201	     * @return ?array<mixed>
202	     */
203	    public function unframed($payload): ?array
204	    {
205	        if (!is_string($payload)) {
206	            return null;
207	        }
208	
209	        $break = strpos($payload, "\n");
210	        if ($break === false || preg_match('/^\d+$/', substr($payload, 0, $break)) !== 1) {
211	            return null;
212	        }
213	
214	        $body = substr($payload, $break + 1);
215	        if (strlen($body) !== (int) substr($payload, 0, $break)) {
216	            return null;
217	        }
218	
219	        $decoded = unserialize($body);
220	
221	        return is_array($decoded) ? $decoded : null;
222	    }
223	
224	    /**
225	     * Collects every worker result and reaps every worker.
226	     *
227	     * Every worker is waited for even after one of them failed, because a
228	     * process left unreaped outlives the run that started it.
229	     *
230	     * @param list<array{pid: int, socket: resource}> $workers
231	     * @param list<mixed> $tail results of the jobs this process took over
232	     *
233	     * @return list<mixed>
234	     *
235	     * @throws DocGenException when a worker died without a usable result
236	     */
237	    public function finish(array $workers, array $tail): array
238	    {
239	        $results = [];
240	        $failure = null;
241	        foreach ($workers as $worker) {
242	            $payload = @stream_get_contents($worker['socket']);
243	            fclose($worker['socket']);
244	            $status = 0;
245	            pcntl_waitpid($worker['pid'], $status);
246	            $result = $this->result($payload, is_int($status) ? $status : -1);
247	            if ($result['ok'] !== true) {
248	                $failure = $failure ?? $result['reason'];
249	                continue;
250	            }
251	
252	            $results[] = $result['result'];
253	        }
254	
255	        if ($failure !== null) {
256	            throw new DocGenException(sprintf('A documentation worker failed: %s', $failure));
257	        }
258	
259	        foreach ($tail as $result) {
260	            $results[] = $result;
261	        }
262	
263	        return $results;
264	    }
265	
266	    /**
267	     * Reads what one worker sent back, or reports why it is unusable.
268	     *
269	     * @param string|false $payload what the worker wrote to its socket
270	     * @param int $status the wait status of the worker process
271	     *
272	     * @return array{ok: bool, result: mixed, reason: ?string}
273	     */
274	    public function result($payload, int $status): array
275	    {
276	        if (!pcntl_wifexited($status) || pcntl_wexitstatus($status) !== 0) {
277	            return ['ok' => false, 'result' => null, 'reason' => 'the worker process stopped before it finished'];
278	        }
279	
280	        $decoded = $this->unframed($payload);
281	        if ($decoded === null || !isset($decoded['ok'])) {
282	            return ['ok' => false, 'result' => null, 'reason' => 'the worker process sent no result'];
283	        }
284	
285	        if ($decoded['ok'] !== true) {
286	            $reason = $decoded['result'] ?? null;
287	
288	            return ['ok' => false, 'result' => null, 'reason' => is_string($reason) ? $reason : 'the job could not be worked'];
289	        }
290	
291	        return ['ok' => true, 'result' => $decoded['result'] ?? null, 'reason' => null];
292	    }
293	
294	    /**
295	     * Returns the jobs from one position onwards.
296	     *
297	     * @template TJob
298	     *
299	     * @param list<TJob> $jobs
300	     *
301	     * @return list<TJob>
302	     */
303	    public function remaining(array $jobs, int $from): array
304	    {
305	        $rest = [];
306	        foreach ($jobs as $index => $job) {
307	            if ($index >= $from) {
308	                $rest[] = $job;
309	            }
310	        }
311	
312	        return $rest;
313	    }
314	}
