23	/**
24	 * Runs the documentation generation for parsed CLI arguments.
25	 */
26	final class DocGenGenerationRunner
27	{
28	    /** @readonly */
29	    private string $workingDirectory;
30	
31	    /** @readonly */
32	    private ConfigLoader $configLoader;
33	
34	    /** @readonly */
35	    private ProjectAnalyzer $analyzer;
36	
37	    /** @readonly */
38	    private SiteRenderer $siteRenderer;
39	
40	    /** @readonly */
41	    private DocGenOutputWriter $writer;
42	
43	    /** @readonly */
44	    private DocGenConfigPathResolver $configPathResolver;
45	
46	    /** @readonly */
47	    private DocGenConfigOverrides $overrides;
48	
49	    /** @readonly */
50	    private DocGenPathResolver $pathResolver;
51	
52	    /** @readonly */
53	    private DocGenPreviewServer $previewServer;
54	
55	    /** @readonly */
56	    private DocGenMemoryLimit $memoryLimit;
57	
58	    /** @readonly */
59	    private DiffWorkspace $workspace;
60	
61	    /**
62	     * Creates a generation runner from pipeline collaborators.
63	     */
64	    public function __construct(
65	        string $workingDirectory,
66	        ?ConfigLoader $configLoader = null,
67	        ?ProjectAnalyzer $analyzer = null,
68	        ?SiteRenderer $siteRenderer = null,
69	        ?DocGenOutputWriter $writer = null,
70	        ?DocGenConfigPathResolver $configPathResolver = null,
71	        ?DocGenConfigOverrides $overrides = null,
72	        ?DocGenPathResolver $pathResolver = null,
73	        ?DocGenPreviewServer $previewServer = null,
74	        ?DocGenMemoryLimit $memoryLimit = null,
75	        ?DiffWorkspace $workspace = null,
76	    ) {
77	        $this->workingDirectory = $workingDirectory;
78	        $this->configLoader = $configLoader ?? new ConfigLoader();
79	        $this->analyzer = $analyzer ?? new ProjectAnalyzer();
80	        $this->siteRenderer = $siteRenderer ?? new SiteRenderer();
81	        $this->writer = $writer ?? new DocGenOutputWriter();
82	        $this->configPathResolver = $configPathResolver ?? new DocGenConfigPathResolver();
83	        $this->overrides = $overrides ?? new DocGenConfigOverrides();
84	        $this->pathResolver = $pathResolver ?? new DocGenPathResolver();
85	        $this->previewServer = $previewServer ?? new DocGenPreviewServer();
86	        $this->memoryLimit = $memoryLimit ?? new DocGenMemoryLimit();
87	        $this->workspace = $workspace ?? new DiffWorkspace(null, null, $this->analyzer);
88	    }
89	
90	    /**
91	     * Generates the site and optionally serves it.
92	     *
93	     * @param array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, help: bool, version: bool} $arguments
94	     */
95	    public function run(array $arguments): int
96	    {
97	        $this->memoryLimit->apply($arguments['memoryLimit']);
98	
99	        try {
100	            $config = $this->overrides->apply($this->loadConfig($arguments['config']), $arguments);
101	            $outputRoot = $this->pathResolver->resolve($config->root, $config->output);
102	            $result = $arguments['base'] === null
103	                ? $this->generate($config, $outputRoot, $arguments['jobs'])
104	                : $this->generateDiff($config, $outputRoot, new RevisionRange($arguments['base'], $arguments['head']), $arguments['jobs']);
105	            $this->report($result['model'], $result['pages'], $outputRoot);
106	
107	            if ($arguments['serve'] !== null) {
108	                $this->writer->write(sprintf("Serving documentation at http://%s (Ctrl-C to stop)\n", $arguments['serve']));
109	
110	                return $this->previewServer->serve($outputRoot, $arguments['serve']);
111	            }
112	        } catch (DocGenException $exception) {
113	            $this->writer->writeError(sprintf("DocGen error: %s\n", $exception->getMessage()));
114	
115	            return 2;
116	        }
117	
118	        return 0;
119	    }
120	
121	    /**
122	     * Analyzes and renders the documented project as it is now.
123	     *
124	     * @return array{model: ProjectModel, pages: int}
125	     *
126	     * @throws DocGenException when the project cannot be analyzed or written
127	     */
128	    public function generate(DocGenConfig $config, string $outputRoot, ?int $workers = null): array
129	    {
130	        $model = $this->analyzer->analyze($config, $workers);
131	
132	        return ['model' => $model, 'pages' => $this->siteRenderer->render($model, $outputRoot, null, $workers)];
133	    }
134	
135	    /**
136	     * Renders the documented project as the comparison of two revisions.
137	     *
138	     * The checkouts of the compared revisions are removed again whatever
139	     * happens while the site is written, because they are scratch copies
140	     * of the repository and nothing may outlive the run.
141	     *
142	     * @return array{model: ProjectModel, pages: int}
143	     *
144	     * @throws DocGenException when a revision cannot be read or analyzed
145	     */
146	    public function generateDiff(DocGenConfig $config, string $outputRoot, RevisionRange $range, ?int $workers = null): array
147	    {
148	        $session = $this->workspace->open($config, $range, $workers);
149	
150	        try {
151	            $pages = $this->siteRenderer->render($session->model, $outputRoot, $session->diff, $workers);
152	            $this->writer->write(sprintf(
153	                "Compared %s to %s\n",
154	                $session->diff->baseLabel(),
155	                $session->diff->headLabel(),
156	            ));
157	
158	            return ['model' => $session->model, 'pages' => $pages];
159	        } finally {
160	            $this->workspace->close($session);
161	        }
162	    }
163	
164	    /**
165	     * Reports what was written and what the analysis could not do.
166	     */
167	    public function report(ProjectModel $model, int $pages, string $outputRoot): void
168	    {
169	        $this->writer->write(sprintf(
170	            "Generated %d pages for %d packages into %s\n",
171	            $pages,
172	            count($model->packages),
173	            $outputRoot,
174	        ));
175	        foreach ($model->warnings as $warning) {
176	            $this->writer->writeError(sprintf("Warning: %s\n", $warning));
177	        }
178	    }
179	
180	    /**
181	     * Loads the configuration file, or builds the zero-config defaults.
182	     *
183	     * @throws DocGenException when an explicitly given config file is invalid
184	     */
185	    public function loadConfig(?string $configOption): DocGenConfig
186	    {
187	        if ($configOption !== null) {
188	            return $this->configLoader->load($this->configPathResolver->resolve($this->workingDirectory, $configOption));
189	        }
190	
191	        $default = $this->configPathResolver->resolve($this->workingDirectory, 'doc.yaml');
192	        if (is_file($default)) {
193	            return $this->configLoader->load($default);
194	        }
195	
196	        $root = realpath($this->workingDirectory);
197	
198	        return new DocGenConfig($root === false ? $this->workingDirectory : $root, ['.', 'packages/*'], [], [], 'build/docs', null, null, null);
199	    }
200	}
